import React, { createContext, useContext, useState, useEffect } from 'react';

const CheckoutContext = createContext();

export const CheckoutProvider = ({ children }) => {
    // 1. Unified Checkout State
    const [shippingData, setShippingData] = useState(() => {
        const saved = localStorage.getItem('bindass_checkout_shipping');
        return saved ? JSON.parse(saved) : {
            firstName: '',
            lastName: '',
            addressLine1: '',
            city: '',
            state: '',
            pincode: '',
            countryCode: 'IN',
            email: '',
            phone: ''
        };
    });

    const [paymentData, setPaymentData] = useState(() => {
        const saved = localStorage.getItem('bindass_checkout_payment');
        return saved ? JSON.parse(saved) : { method: 'card', lastFour: 'XXXX' };
    });

    const [checkoutTotals, setCheckoutTotals] = useState(() => {
        const saved = localStorage.getItem('bindass_checkout_totals');
        return saved ? JSON.parse(saved) : { subtotal: 0, tax: 0, totalAmount: 0 };
    });

    // 2. Persistence Layer
    useEffect(() => {
        localStorage.setItem('bindass_checkout_shipping', JSON.stringify(shippingData));
    }, [shippingData]);

    useEffect(() => {
        localStorage.setItem('bindass_checkout_payment', JSON.stringify(paymentData));
    }, [paymentData]);

    useEffect(() => {
        localStorage.setItem('bindass_checkout_totals', JSON.stringify(checkoutTotals));
    }, [checkoutTotals]);

    // 3. Actions
    const updateShipping = (data) => setShippingData(prev => ({ ...prev, ...data }));
    const updatePayment = (data) => setPaymentData(prev => ({ ...prev, ...data }));
    const updateTotals = (data) => setCheckoutTotals(prev => ({ ...prev, ...data }));

    const clearCheckout = () => {
        localStorage.removeItem('bindass_checkout_shipping');
        localStorage.removeItem('bindass_checkout_payment');
        localStorage.removeItem('bindass_checkout_totals');
        setShippingData({
            firstName: '',
            lastName: '',
            addressLine1: '',
            city: '',
            state: '',
            pincode: '',
            countryCode: 'IN',
            email: '',
            phone: ''
        });
        setPaymentData({ method: 'card', lastFour: 'XXXX' });
        setCheckoutTotals({ subtotal: 0, tax: 0, totalAmount: 0 });
    };

    return (
        <CheckoutContext.Provider value={{ 
            shippingData, updateShipping, 
            paymentData, updatePayment, 
            checkoutTotals, updateTotals, 
            clearCheckout 
        }}>
            {children}
        </CheckoutContext.Provider>
    );
};

export const useCheckout = () => {
    const context = useContext(CheckoutContext);
    if (!context) {
        throw new Error('useCheckout must be used within a CheckoutProvider');
    }
    return context;
};
